/*
 * prog48_sorted_linked_list.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program builds a singly linked list that
 * is kept sorted in ascending order while it reads integer arguments
 * from the command line.  After all arguments have been processed it
 * prints the list (or the word “EMPTY” if the list is empty) exactly as
 * the original binary does.
 *
 * The original binary used a flattened control‑flow and a fixed‑size
 * storage pool (64 elements).  The source below reproduces the same
 * observable behaviour without the obfuscation.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64          /* maximum number of values that can be stored */

/* storage pool for the linked list */
static long  value[MAX_NODES];   /* the integer stored in each node */
static int   next[MAX_NODES];    /* index of the next node, -1 = end of list */
static int   head = -1;          /* index of the first node, -1 = empty list */
static int   used = 0;           /* number of nodes already allocated */

/* --------------------------------------------------------------------- */
/* Insert a new value into the list, keeping the list sorted ascending.  */
/* The function assumes that `used` is still within the array bounds.    */
/* --------------------------------------------------------------------- */
static void insert_sorted(long v)
{
    int new_idx = used;          /* index of the node we are about to add */
    value[new_idx] = v;
    next[new_idx]  = -1;         /* will be overwritten if we insert elsewhere */

    /* If the list is empty or the new value belongs before the current head,
       insert it at the front. */
    if (head == -1 || value[head] > v) {
        next[new_idx] = head;
        head = new_idx;
        return;
    }

    /* Otherwise walk the list to find the insertion point. */
    int cur = head;
    while (next[cur] != -1 && value[next[cur]] <= v) {
        cur = next[cur];
    }

    /* Insert the new node after `cur`. */
    next[new_idx] = next[cur];
    next[cur]     = new_idx;
}

/* --------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* Build the sorted list from the command‑line arguments. */
    for (int i = 1; i < argc && used < MAX_NODES; ++i) {
        char *endptr = NULL;
        long  v = strtol(argv[i], &endptr, 10);

        /* The original program ignored malformed arguments; we do the same. */
        if (endptr == argv[i] || *endptr != '\0')
            continue;

        insert_sorted(v);
        ++used;
    }

    /* Output the result. */
    if (head == -1) {
        puts("EMPTY");
    } else {
        int idx = head;
        while (idx != -1) {
            printf("%ld", value[idx]);
            idx = next[idx];
            if (idx != -1)
                putchar(' ');
        }
        putchar('\n');
    }

    return 0;
}
